// Sound effects, by name: first the user's own library (any MP3 dropped into DURAK_SFX_DIR,
// default ~/Documents/durak-sfx, used by its file name), then the CC0 recordings from Freesound
// in assets/sfx (sources.json says where each came from). The table's own sounds are added
// under every card move, and a sound described in words is generated by ElevenLabs and cached.
import crypto from 'node:crypto';
import { existsSync } from 'node:fs';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { elevenLabsKey } from './voice.mjs';

export const SFX_DIR = 'output/sfx';
const LIBRARY = 'assets/sfx';
/** The user's own sounds: kept outside the repo, so nothing uncleared is committed. */
export const USER_LIBRARY =
  process.env.DURAK_SFX_DIR ?? path.join(os.homedir(), 'Documents', 'durak-sfx');
const USER_VOLUME = 0.75;

/** Named effects in the library, at their mix volume. The laugh sits low: funny, ironically. */
export const PRESETS = {
  slap: 0.8,
  swoosh: 0.5,
  draw: 0.6,
  shuffle: 0.7,
  boom: 0.9,
  scratch: 0.8,
  crickets: 0.6,
  cough: 0.8,
  trombone: 0.7,
  laugh: 0.35,
  giggle: 0.45,
  drumroll: 0.6,
  gasp: 0.7,
  ding: 0.6,
  airhorn: 0.5,
  whoosh: 0.6,
  sting: 0.6,
  bonk: 0.8,
};

/**
 * A named sound's file (the user's library first, so it can replace a CC0 one), or the prompt
 * and length for a described one. A name with no spaces that is in neither library is a typo,
 * not a prompt. `for` cuts a library sound short.
 */
export function sound(item) {
  const cut = item.for ? { for: item.for } : {};
  const own = path.join(USER_LIBRARY, `${item.sfx}.mp3`);
  if (existsSync(own)) return { file: own, volume: item.volume ?? USER_VOLUME, ...cut };
  const volume = PRESETS[item.sfx];
  if (volume !== undefined)
    return { file: path.join(LIBRARY, `${item.sfx}.mp3`), volume: item.volume ?? volume, ...cut };
  if (!/\s/.test(item.sfx))
    throw new Error(
      `Sound "${item.sfx}" is in neither ${USER_LIBRARY} nor ${LIBRARY}; describe a sound in words to generate one`,
    );
  return { prompt: item.sfx, seconds: (item.for ?? 1500) / 1000, volume: item.volume ?? 0.8 };
}

export function sfxFile({ prompt, seconds }) {
  const hash = crypto.createHash('sha1').update(`${prompt}\n${seconds}`).digest('hex').slice(0, 16);
  return path.join(SFX_DIR, `${hash}.mp3`);
}

/** The table's own sounds for a resolved scene's beats: a slap as each card lands, and so on. */
export function tableSounds(beats) {
  const sounds = [];
  for (const beat of beats) {
    // Lands with the card: the hand lets go at 540 ms and it glides for 260 more.
    if (beat.do === 'play' || beat.do === 'defend') sounds.push({ at: beat.at + 800, sfx: 'slap' });
    else if (beat.do === 'pickup') sounds.push({ at: beat.at + 600, sfx: 'swoosh' });
    else if (beat.do === 'draw')
      for (let n = 0; n < (beat.count ?? 1); n++)
        sounds.push({ at: beat.at + n * 650 + 450, sfx: 'draw' });
    else if (beat.do === 'discard') sounds.push({ at: beat.at, sfx: 'shuffle' });
  }
  return sounds;
}

/** The files for the sound items, in order; a described sound is generated once and cached. */
export async function ensureSounds(items, { log = console.log } = {}) {
  await fs.mkdir(SFX_DIR, { recursive: true });
  let key;
  const out = [];
  for (const item of items) {
    const spec = sound(item);
    if (spec.file) {
      out.push({ at: item.at, file: spec.file, volume: spec.volume, for: spec.for });
      continue;
    }
    const file = sfxFile(spec);
    const cached = await fs.stat(file).then(
      () => true,
      () => false,
    );
    if (!cached) {
      key ??= await elevenLabsKey();
      const response = await fetch(
        'https://api.elevenlabs.io/v1/sound-generation?output_format=mp3_44100_128',
        {
          method: 'POST',
          headers: { 'xi-api-key': key, 'content-type': 'application/json' },
          body: JSON.stringify({
            text: spec.prompt,
            duration_seconds: Math.min(30, Math.max(0.5, spec.seconds)),
            prompt_influence: 0.6,
          }),
        },
      );
      if (!response.ok) {
        const body = await response.text();
        throw new Error(`Sound "${item.sfx}": HTTP ${response.status} ${body.slice(0, 200)}`);
      }
      await fs.writeFile(file, Buffer.from(await response.arrayBuffer()));
      log(`  sound   ${spec.seconds}s  ${item.sfx}`);
    }
    out.push({ at: item.at, file, volume: spec.volume });
  }
  return out;
}
